#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    // l/r 从数组两端出发，先考虑宽度最大的容器。
    int ans = 0, i = 0, l = 0, n = 0, r = 0;
    n = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    l = 0;
    r = (n - 1);
    ans = 0;
    while (l < r) {
        // 当前面积由宽度乘较矮高度得到，先保留它再移动边界。
        ans = mx(ans, ((r - l) * mn(a[l], a[r])));
        // 移动较矮的一边：固定它只会让宽度变小，无法获得更优面积。
        if (a[l] < a[r]) {
            l = (l + 1);
        }
        else {
            r = (r - 1);
        }
    }
    // 两指针相遇后，ans 保存全部安全筛选过程中的最大面积。
    emit(ans);
    return 0;
}

